const entrada = $('Receber clientes').first().json;
const clientes = entrada.body?.clientes ?? entrada.clientes;

if (!Array.isArray(clientes) || clientes.length === 0) {
  throw new Error('Envie um JSON no formato {\"clientes\": [...]}');
}

const csv = $json.csv ?? $json.data ?? $json.body;
if (typeof csv !== 'string' || !csv.trim()) {
  throw new Error('Nao foi possivel ler o CSV de investimentos.');
}

const linhas = csv.trim().replace(/^\uFEFF/, '').split(/\r?\n/);
const cabecalhos = linhas.shift().split(',').map((valor) => valor.trim());
const investimentos = linhas.filter(Boolean).map((linha) => {
  const valores = linha.split(',').map((valor) => valor.trim());
  return Object.fromEntries(cabecalhos.map((campo, indice) => [campo, valores[indice]]));
});

function paraNumeroBR(valor) {
  if (typeof valor === 'number') return valor;
  const limpo = String(valor ?? '').replace(/R\$|\s/g, '').replace(/\./g, '').replace(',', '.');
  const numero = Number(limpo);
  if (!Number.isFinite(numero)) throw new Error(`Saldo invalido: ${valor}`);
  return numero;
}

const recomendacoes = clientes.map((cliente) => {
  const saldo = paraNumeroBR(cliente.saldo);
  const perfil = String(cliente.perfil ?? '').trim();
  const opcoes = investimentos.filter((item) =>
    item.perfil.toLocaleLowerCase('pt-BR') === perfil.toLocaleLowerCase('pt-BR') &&
    Number(item.minimo) <= saldo
  );

  const produtos = opcoes.map((item) => ({
    produto: item.produto,
    investimento_minimo: Number(item.minimo),
    rentabilidade: item.rentabilidade,
  }));
  const lista = produtos.length
    ? produtos.map((item) => `${item.produto} (${item.rentabilidade})`).join(', ')
    : 'nenhum produto da base atende ao saldo informado';
  const foco = {
    Conservador: 'seguranca e renda fixa',
    Moderado: 'equilibrio entre renda fixa e renda variavel',
    Arrojado: 'maior potencial de retorno, aceitando mais oscilacoes',
  }[perfil] ?? 'produtos compativeis com o perfil informado';

  return {
    nome: cliente.nome,
    email: cliente.email,
    saldo,
    perfil,
    produtos,
    mensagem: `Ola, ${cliente.nome}! Para o seu perfil ${perfil}, com foco em ${foco}, encontramos: ${lista}. Esta mensagem tem carater educativo e nao constitui recomendacao individual de investimento.`,
  };
});

return [{ json: { sucesso: true, total: recomendacoes.length, recomendacoes } }];
